<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require __DIR__.'/includes/project_manager.php';require_permission('projects.manage');$pdo=db();$id=max(0,(int)($_GET['id']??$_POST['id']??0));$project=$id?pm_fetch_project($pdo,$id):null;$pageTitle=$project?'Editar proyecto':'Nuevo proyecto';$clients=$pdo->query("SELECT id,company_name FROM clients WHERE status<>'inactive' ORDER BY company_name")->fetchAll();$users=$pdo->query('SELECT id,name FROM users WHERE is_active=1 ORDER BY name')->fetchAll();$deals=$pdo->query("SELECT id,title,client_id,amount,currency,owner_user_id FROM deals WHERE status='won' ORDER BY closed_at DESC,id DESC LIMIT 200")->fetchAll();$errors=[];$v=fn($k,$d='')=>$_POST[$k]??($project[$k]??$d);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim((string)($_POST['name']??''));if($name==='')$errors[]='El nombre es obligatorio.';$status=(string)($_POST['status']??'planning');if(!in_array($status,['planning','active','on_hold','completed','cancelled'],true))$status='planning';$health=(string)($_POST['health']??'on_track');if(!in_array($health,['on_track','at_risk','off_track'],true))$health='on_track';$priority=(string)($_POST['priority']??'normal');if(!in_array($priority,['low','normal','high','urgent'],true))$priority='normal';$currency=(string)($_POST['currency']??'USD');if(!in_array($currency,['CLP','USD','BRL'],true))$currency='USD';$billing=(string)($_POST['billing_model']??'fixed');if(!in_array($billing,['fixed','hourly','retainer','internal'],true))$billing='fixed';$client=(int)($_POST['client_id']??0)?:null;$deal=(int)($_POST['deal_id']??0)?:null;$owner=(int)($_POST['owner_user_id']??0)?:null;$code=trim((string)($_POST['code']??''))?:null;$data=[$client,$deal,$owner,$name,$code,trim((string)($_POST['description']??''))?:null,$status,$health,$priority,($_POST['start_date']??'')?:null,($_POST['due_date']??'')?:null,max(0,min(100,(int)($_POST['progress']??0))),max(0,(float)($_POST['budget']??0)),$currency,$billing,max(0,(float)($_POST['hourly_rate']??0)),preg_match('/^#[0-9a-fA-F]{6}$/',(string)($_POST['color']??''))?$_POST['color']:'#0074c7',trim((string)($_POST['notes']??''))?:null];if(!$errors){try{if($id){$pdo->prepare('UPDATE projects SET client_id=?,deal_id=?,owner_user_id=?,name=?,code=?,description=?,status=?,health=?,priority=?,start_date=?,due_date=?,progress=?,budget=?,currency=?,billing_model=?,hourly_rate=?,color=?,notes=?,completed_at=CASE WHEN ?=\'completed\' THEN COALESCE(completed_at,NOW()) ELSE NULL END WHERE id=?')->execute([...$data,$status,$id]);}else{$pdo->prepare('INSERT INTO projects(client_id,deal_id,owner_user_id,name,code,description,status,health,priority,start_date,due_date,progress,budget,currency,billing_model,hourly_rate,color,notes,created_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([...$data,(int)$_SESSION['user_id']]);$id=(int)$pdo->lastInsertId();if($owner)$pdo->prepare('INSERT IGNORE INTO project_members(project_id,user_id,role_name) VALUES (?,?,?)')->execute([$id,$owner,'Project Manager']);}flash('success','Proyecto guardado.');redirect('project_view.php?id='.$id);}catch(Throwable $e){$errors[]='No fue posible guardar. Revisa que el código del proyecto no esté repetido.';}}}
require __DIR__.'/includes/header.php';?><?php foreach($errors as$e):?><div class="alert alert-error"><?=e($e)?></div><?php endforeach;?>
<form method="post" class="panel"><div class="panel-header"><div><h2><?=$project?'Editar proyecto':'Crear proyecto'?></h2><span class="table-sub">Define alcance, responsable, presupuesto, fechas y estado.</span></div><a class="btn btn-light btn-small" href="<?=$project?'project_view.php?id='.$id:'projects.php'?>">Volver</a></div><div class="panel-body form-grid"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><label class="full">Nombre del proyecto *<input name="name" required value="<?=e($v('name'))?>" placeholder="Ej.: Rediseño web Costamat 2026"></label><label>Código<input name="code" value="<?=e($v('code'))?>" placeholder="SOC-2026-001"></label><label>Cliente<select name="client_id"><option value="0">Proyecto interno / sin cliente</option><?php foreach($clients as$c):?><option value="<?=$c['id']?>" <?=(int)$v('client_id',(int)($_GET['client_id']??0))===(int)$c['id']?'selected':''?>><?=e($c['company_name'])?></option><?php endforeach;?></select></label><label>Negocio ganado<select name="deal_id"><option value="0">Sin negocio asociado</option><?php foreach($deals as$d):?><option value="<?=$d['id']?>" <?=(int)$v('deal_id',(int)($_GET['deal_id']??0))===(int)$d['id']?'selected':''?>><?=e($d['title'])?></option><?php endforeach;?></select></label><label>Project Manager<select name="owner_user_id"><option value="0">Sin asignar</option><?php foreach($users as$u):?><option value="<?=$u['id']?>" <?=(int)$v('owner_user_id',$_SESSION['user_id'])===(int)$u['id']?'selected':''?>><?=e($u['name'])?></option><?php endforeach;?></select></label><label>Estado<select name="status"><?php foreach(['planning','active','on_hold','completed','cancelled'] as$x):?><option value="<?=$x?>" <?=$v('status','planning')===$x?'selected':''?>><?=e(pm_status_label($x))?></option><?php endforeach;?></select></label><label>Salud<select name="health"><?php foreach(['on_track','at_risk','off_track'] as$x):?><option value="<?=$x?>" <?=$v('health','on_track')===$x?'selected':''?>><?=e(pm_health_label($x))?></option><?php endforeach;?></select></label><label>Prioridad<select name="priority"><?php foreach(['low','normal','high','urgent'] as$x):?><option value="<?=$x?>" <?=$v('priority','normal')===$x?'selected':''?>><?=e(pm_priority_label($x))?></option><?php endforeach;?></select></label><label>Inicio<input type="date" name="start_date" value="<?=e($v('start_date'))?>"></label><label>Entrega<input type="date" name="due_date" value="<?=e($v('due_date'))?>"></label><label>Avance manual %<input type="number" min="0" max="100" name="progress" value="<?=e($v('progress',0))?>"></label><label>Presupuesto<input type="number" step="0.01" min="0" name="budget" value="<?=e($v('budget',0))?>"></label><label>Moneda<select name="currency"><?php foreach(['CLP','USD','BRL'] as$x):?><option <?=$v('currency','USD')===$x?'selected':''?>><?=$x?></option><?php endforeach;?></select></label><label>Modelo<select name="billing_model"><?php foreach(['fixed'=>'Precio fijo','hourly'=>'Por hora','retainer'=>'Retainer / mensual','internal'=>'Interno'] as$k=>$lab):?><option value="<?=$k?>" <?=$v('billing_model','fixed')===$k?'selected':''?>><?=$lab?></option><?php endforeach;?></select></label><label>Tarifa por hora<input type="number" step="0.01" min="0" name="hourly_rate" value="<?=e($v('hourly_rate',0))?>"></label><label>Color<input type="color" name="color" value="<?=e($v('color','#0074c7'))?>"></label><label class="full">Descripción<textarea name="description" rows="4"><?=e($v('description'))?></textarea></label><label class="full">Notas internas<textarea name="notes" rows="4"><?=e($v('notes'))?></textarea></label><div class="full form-actions"><a class="btn btn-light" href="<?=$project?'project_view.php?id='.$id:'projects.php'?>">Cancelar</a><button class="btn btn-primary">GUARDAR PROYECTO</button></div></div></form><?php require __DIR__.'/includes/footer.php';?>
